        public static readonly CommandNodeNarrativeLine[] EvidenceHigh={
            new("evidence_high-01",NarrativeSpeakerId.Aria,"The released critical-path audit proves Qassem’s role and preserves the verified links gathered in this operation. External financiers and Vanguard connections remain subject to investigation.","گزارش ضروری منتشرشده، نقش قاسم رو ثابت می‌کنه و ارتباط‌های تأییدشدهٔ این عملیات رو حفظ می‌کنه. سرمایه‌گذارهای بیرونی و ارتباط‌های ونگارد همچنان نیاز به بررسی دارن."),
        };
        public static readonly CommandNodeNarrativeLine[] EvidenceLow={
            new("evidence_low-01",NarrativeSpeakerId.Aria,"The complete critical-path audit proves Qassem’s guilt. Parts of the wider support network remain disputed or hidden; that uncertainty does not undo the ending.","گزارش کامل و ضروری، گناه قاسم رو ثابت می‌کنه. بخش‌هایی از شبکهٔ پشتیبانی بزرگ‌تر پنهان یا مورد اختلافه؛ این ابهام پایان رو از بین نمی‌بره."),
