        public static readonly CommandNodeNarrativeLine[] InfrastructureHigh={
            new("infrastructure_high-01",NarrativeSpeakerId.Samira,"The recorded operations preserved essential services without losing their teams. Roads, power, Fuel, clinics, shelters and trade can resume with a stronger base for repairs.","عملیات‌های ثبت‌شده خدمات ضروری و تیم‌هاشون رو حفظ کردن. راه‌ها، برق، سوخت، درمانگاه‌ها، پناهگاه‌ها و تجارت با پایهٔ سالم‌تری برای تعمیرها دوباره راه می‌افتن."),
