        public static readonly CommandNodeNarrativeLine[] Postscript={
            new("postscript-01",NarrativeSpeakerId.Aria,"The Story Archive now holds all five reconstructed Protocol Fragments, the complete audit and the recovery emphasis. The Campaign is complete.","آرشیو داستان حالا هر پنج قطعهٔ بازسازی‌شدهٔ پروتکل، گزارش کامل و تأکید بازسازی رو نگه می‌داره. کارزار کامل شده."),
            new("postscript-02",NarrativeSpeakerId.Aria,"External Vanguard links remain under review. No immediate threat is confirmed. These are future investigations, not an unfinished ending.","ارتباط‌های بیرونی ونگارد همچنان در دست بررسیه. تهدید فوری تأیید نشده. این‌ها بررسی‌های آینده‌ان، نه پایانی ناتمام."),
            new("postscript-03",NarrativeSpeakerId.Commander,"Then we do not invent a threat. Open the restored operations map for replay. This city has work ahead, and room to live.","پس تهدیدی اختراع نمی‌کنیم. نقشهٔ عملیات بازیابی‌شده رو برای مرور دوباره باز کنین. این شهر کار پیش رو داره و جایی برای زندگی."),
        };
